<template><q-page class="q-pa-lg"><div class="row items-center"><div><div class="page-title">Announcements</div><div class="muted">Share important updates with your team.</div></div><q-space/><q-btn color="primary" unelevated rounded icon="add" label="Create Announcement" @click="open()"/></div><q-card flat bordered class="q-mt-lg"><q-table :rows="rows" :columns="columns" row-key="id" :loading="loading"><template #body-cell-priority="p"><q-td><q-badge :color="priorityColor(p.row.priority)" :label="cap(p.row.priority)"/></q-td></template><template #body-cell-target_audience="p"><q-td><q-badge color="blue-grey-2" text-color="blue-grey-9" :label="audienceLabel(p.row.target_audience)"/></q-td></template><template #body-cell-actions="p"><q-td><q-btn flat round icon="edit" @click="open(p.row)"/><q-btn flat round icon="delete" color="negative" @click="remove(p.row)"/></q-td></template></q-table></q-card><q-dialog v-model="dialog"><q-card style="min-width:min(520px,92vw)"><q-card-section class="text-h6">{{ form.id?'Edit':'Create' }} Announcement</q-card-section><q-card-section class="q-gutter-md"><q-input v-model="form.title" label="Title" outlined/><q-input v-model="form.message" label="Message" outlined type="textarea" autogrow/><div class="row q-col-gutter-md"><q-select class="col" v-model="form.priority" :options="priorities" label="Priority" outlined map-options emit-value :option-label="cap"/><q-select class="col" v-model="form.target_audience" :options="audiences" label="Target audience" outlined map-options emit-value :option-label="audienceLabel"/></div></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" v-close-popup/><q-btn color="primary" label="Save" :loading="saving" @click="save"/></q-card-actions></q-card></q-dialog></q-page></template>
<script setup>import {ref,onMounted} from 'vue';import {useQuasar} from 'quasar';import api from '../services/api';const $q=useQuasar(),rows=ref([]),loading=ref(false),saving=ref(false),dialog=ref(false),form=ref({title:'',message:'',priority:'normal',target_audience:'all'}),priorities=['normal','important','urgent'],audiences=['all','managers','employees'];const cap=x=>x?x[0].toUpperCase()+x.slice(1):'';const audienceLabel=x=>({all:'Everyone',managers:'Managers',employees:'Employees'})[x]||x;const priorityColor=x=>x==='urgent'?'negative':x==='important'?'orange':'positive';const columns=[{name:'title',label:'Title',field:'title',align:'left'},{name:'message',label:'Message',field:'message',align:'left'},{name:'priority',label:'Priority',field:'priority'},{name:'target_audience',label:'Audience',field:'target_audience'},{name:'creator_name',label:'Posted by',field:'creator_name'},{name:'created_at',label:'Created',field:'created_at'},{name:'actions',label:'Actions',field:'actions'}];async function load(){loading.value=true;try{rows.value=(await api.get('/announcements')).data.data}finally{loading.value=false}}function open(row){form.value=row?{...row}:{title:'',message:'',priority:'normal',target_audience:'all'};dialog.value=true}async function save(){saving.value=true;try{if(form.value.id)await api.put(`/announcements/${form.value.id}`,form.value);else await api.post('/announcements',form.value);dialog.value=false;$q.notify({type:'positive',message:'Announcement saved'});load()}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Unable to save'})}finally{saving.value=false}}async function remove(row){if(!confirm(`Delete "${row.title}"?`))return;try{await api.delete(`/announcements/${row.id}`);$q.notify({type:'positive',message:'Announcement deleted'});load()}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Unable to delete'})}}onMounted(load)</script>